    const reversedImages = appendReverted ? images.slice().reverse().join(' ') : '';
    const command = `convert -delay ${delay} ${images.join(' ')} ${reversedImages} -resize ${targetSize} ${gifPath}`;

    exec(command, (error) => {
        if (error) {
            ctx.status = 500;
            ctx.body = { error: 'Failed to create GIF.' };
            return;
